"""Embed web/index.html into the ESP32 firmware as firmware/Reach/page_html.h.

Run after every edit to web/index.html, then re-upload the sketch:
    python tools/embed_page.py
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "web" / "index.html"
DST = ROOT / "firmware" / "Reach" / "page_html.h"
DELIM = "HTML"

html = SRC.read_text(encoding="utf-8")
if f"){DELIM}\"" in html:
    raise SystemExit(f"index.html contains ')' + {DELIM!r} + '\"', which would end the raw string early")

DST.write_text(
    "// GENERATED by tools/embed_page.py from web/index.html. Do not edit by hand.\n"
    "#pragma once\n"
    f"const char PAGE[] PROGMEM = R\"{DELIM}({html}){DELIM}\";\n",
    encoding="utf-8",
)
print(f"Wrote {DST.relative_to(ROOT)} ({len(html)} bytes of HTML)")
